"""runtime — A 路接入点(被 voice_agent.py 的 [OPENCODE-A/B] 补丁调用)

统一口径：**意图识别走拼音标注** —— 转写 → 拼音标注 → 折叠音节掩码 → 精确查表。
  a_path_preempt(agent, text)    : 段转写完成后识别; live 命中且 additive 且非破坏性 → 提前执行, 返回 True
  partial_preempt(agent, partial): 部分文本逐前缀识别; 同左侧
开关来自【当前 profile 的 behavior】(fastpath_mode / fastpath_table / fastpath_min_prefix)，
环境变量可覆盖(测试用)。影子模式两者都只记录(不改写原流程)。
"""
from __future__ import annotations

import os
import time

from .hook import get_fp


def _annotate(text):
    try:
        from .pinyin import annotate
        return annotate(text)
    except Exception:
        return ""


def _dispatch(agent, intent, arg):
    from actions import dispatch  # voice_agent 同目录
    return dispatch(intent, arg, agent.cfg, dry=getattr(agent, "dry", False))


def _akey_safe(intent, arg):
    try:
        from voice_agent import _akey
        return _akey(intent, arg)
    except Exception:
        return f"{intent}|{arg}"


def _record(agent, text, fr, path, early):
    from dlog import log
    ok, msg, _info = _dispatch(agent, fr["intent"], fr["arg"])
    if ok:
        try:
            agent._a_executed.add(_akey_safe(fr["intent"], fr["arg"]))
            agent._a_actions.append({"text": (text or "").strip(),
                                     "intent": fr["intent"], "arg": fr["arg"]})
        except Exception:
            pass
        log(f"   ✅ 拼音识别{'提前' if early else ''}执行 {fr['intent']}({fr['arg']})"
            f" → {msg}   ← 「{(text or '').strip()}」", "ACT")
    else:
        # ⚠️ 血债：原来只记一行 MIC（debug 看不见）就 return False，
        #   整句掉回主路径 → 「调整静音。」被当听写打进终端（用户实测）。
        #   现在分两种：
        #     · 动作没注册（未知意图）→ 仍交回主路径，但用 WARN 喊出来
        #     · 动作存在但执行失败 → **消费掉这句话**（不许再掉进听写），并把原因说出来
        _unregistered = "未知意图" in str(msg)
        log(f"   ⚠️ 拼音识别命中 {fr['intent']}，但执行失败：{msg}"
            + ("（动作未注册 → 交回主路径；DEBUG 里可查启动时的注册告警）"
               if _unregistered else "（本句不再走听写）"), "WARN")
        if not _unregistered:
            try:
                agent._a_executed.add(_akey_safe(fr["intent"], fr["arg"]))
                agent._a_actions.append({"text": (text or "").strip(),
                                         "intent": fr["intent"], "arg": fr["arg"]})
            except Exception:
                pass
            return True
    fp = get_fp(getattr(agent, "cfg", None))
    if fp:
        fp._log("a_path", {"ts": time.time(), "path": path, "text": (text or "").strip(),
                           "pinyin": _annotate(text), "intent": fr.get("intent"),
                           "arg": fr.get("arg"), "fire_at": fr.get("fire_at"),
                           "start": fr.get("start"), "ok": bool(ok), "mode": fp.mode})
    return ok


def _pattern_hit(agent, text):
    """模式命中（带变量的命令）→ 伪 fr（给 _record 用）"""
    try:
        from . import intents as _intents
        m = _intents.match_pattern(text)
        if not m:
            return None
        intent, arg = m
        if not _intents.enabled(getattr(agent, "cfg", None), intent):
            return None
        return {"intent": intent, "arg": arg, "additive": True, "blocked": False,
                "kind": 1, "span": None, "fire_at": None, "start": None}
    except Exception:
        return None


def a_path_preempt(agent, text):
    try:
        return _a_path_preempt(agent, text)
    except Exception as e:
        # ★ 不许静默（血债：这里一抛异常，"关闭输入"就悄无声息地掉进听写）
        try:
            from dlog import log
            log(f"   ⚠️ 拼音路由异常（已忽略）: {type(e).__name__}: {e}", "WARN")
        except Exception:
            pass
        return False


def _a_path_preempt(agent, text):
    cfg = getattr(agent, "cfg", None)
    # ★ 先试【带变量】的模式匹配（「打开第5条」这种掩码表做不了）
    _ph = _pattern_hit(agent, text)
    if _ph is not None:
        try:
            from dlog import log
            log(f"   [OPENCODE] 模式命中 {_ph['intent']}({_ph['arg']}) ← 「{(text or '').strip()}」",
                "ASR", sub=True)
        except Exception:
            pass
        return _record(agent, text, _ph, "a_pattern", early=False)
    fp = get_fp(cfg)
    from .hook import get_system_fp
    sys_fp = get_system_fp(cfg)       # ★ 唯一开关（intent_registry）：任何领域都按它来
    if (fp is None and sys_fp is None) or not (text or "").strip():
        return False
    fr = None
    if fp is not None:
        fr = fp.route_prefix(text)          # ★ 全子串：前后缀不影响命中
    if (fr is None or fr["decision"] != "hit") and sys_fp is not None:
        fr2 = sys_fp.route_prefix(text)
        if fr2["decision"] == "hit":
            fr, fp = fr2, sys_fp
        elif fr is None:
            fr = fr2
    if fr is None:
        return False
    py = _annotate(text)
    if fr["decision"] != "hit":
        try:
            from dlog import log
            log(f"   [OPENCODE] 拼音识别: {py} → MISS", "ASR", sub=True)
        except Exception:
            pass
        if fp is not None:
            fp._log("a_path", {"ts": time.time(), "path": "a_full", "text": text.strip(),
                               "pinyin": py, "decision": "miss", "mode": fp.mode})
        return False
    tag = f"{fr['intent']}({fr['arg']})"
    # ★★ 假命中护栏（2026-10-19 用户实测）：`tail_only` 只要求"结束在句尾"，配上【前缀行】
    #   （kind=2，为"逐字早火"做的）就会出现「让AI看看」这种句子里的 3 字片段撞上
    #   InfoQ 的前缀行 → 被当成 open_url。整句路由（A 路/B 路兜底）只认【整条说法】命中
    #   （kind=1）；前缀行留给 partial_preempt（逐字早火）用。
    #   ★ 2026-10-19 晚：匹配已改为【全子串】（前后缀不影响），这条护栏更加重要 ——
    #     子串扫描会让 kind=2 的短片段更容易撞上，所以整句路由仍然只认 kind=1。
    if fr.get("kind") == 2:
        try:
            from dlog import log
            log(f"   [OPENCODE] 拼音识别: {py} → 只命中前缀行「{fr.get('span')}」"
                f"→ 不执行（防假命中；整句路由只认整条说法）", "MIC", sub=True)
        except Exception:
            pass
        return False
    if _akey_safe(fr["intent"], fr["arg"]) in getattr(agent, "_a_executed", set()):
        return False
    if fp.mode == "live" and fr.get("additive") and not fr.get("blocked"):
        try:
            from dlog import log
            log(f"   [OPENCODE] 拼音识别: {py} → HIT {tag}", "ASR", sub=True)
        except Exception:
            pass
        return _record(agent, text, fr, "a_full", early=False)
    # 影子 / 非 additive / 破坏性: 只记录（★ 必须可见：不然"为什么没执行"查不出来）
    try:
        from dlog import log
        log(f"   [OPENCODE] 拼音识别: {py} → 命中 {tag} 但不执行"
            f"（mode={fp.mode} additive={fr.get('additive')} blocked={fr.get('blocked')}）",
            "WARN")
    except Exception:
        pass
    fp._log("a_path", {"ts": time.time(), "path": "a_full", "text": text.strip(),
                       "pinyin": py, "intent": fr.get("intent"), "arg": fr.get("arg"),
                       "decision": "hit", "would_exec": True, "mode": fp.mode,
                       "additive": fr.get("additive"), "blocked": fr.get("blocked")})
    return False


def partial_preempt(agent, partial):
    cfg = getattr(agent, "cfg", None)
    fp = get_fp(cfg)
    if fp is None or len((partial or "").strip()) < 2:
        return False
    fr = fp.route_prefix(partial)          # ★ 全子串（部分文本通常含填充词）
    if fr["decision"] != "hit" or fr.get("blocked"):
        return False
    if _akey_safe(fr["intent"], fr["arg"]) in getattr(agent, "_a_executed", set()):
        return False
    if fp.mode != "live":
        fp._log("a_path", {"ts": time.time(), "path": "a_partial", "text": partial.strip(),
                           "pinyin": _annotate(partial), "intent": fr.get("intent"),
                           "arg": fr.get("arg"), "would_exec": True, "mode": fp.mode})
        return False
    return _record(agent, partial, fr, "a_partial", early=True)


def b_try(agent, text, dur=None, raw=None):
    """B 路兜底（整句、全子串）：命中唯一意图清单 → 直接执行，不再掉进听写

    为什么要有：A 路（流式抢跑）只在有分段/流式时跑；一旦它是 MISS 或执行异常，
    这句话会走到主路径 → 规则/模型 unknown → **听写**。
    实测血债：「调整静音。」就是这么被打进终端的。这里再查一遍整句，
    命中就当场执行（并且记账，避免 B 路重复执行）。
    """
    if not (text or "").strip():
        return False
    # ★ 带变量的模式（「打开第 5 条」「刷新收藏夹」）优先
    _ph = _pattern_hit(agent, text)
    if _ph is not None:
        try:
            from dlog import log
            log(f"   [OPENCODE] B 路模式命中 {_ph['intent']}({_ph['arg']})"
                f" ← 「{text.strip()}」", "MIC", sub=True)
        except Exception:
            pass
        _record(agent, text, _ph, "b_pattern", early=False)
        return True
    cfg = getattr(agent, "cfg", None)
    from .hook import get_system_fp
    fp = get_system_fp(cfg)
    if fp is None:
        return False
    fr = fp.route_prefix(text)             # ★ 全子串（前后缀不影响）
    if fr["decision"] != "hit":
        return False
    # ★ 假命中护栏：整句兜底只认【整条说法】命中（kind=1）；只命中"前缀行"的片段
    #   （kind=2，例如「让AI看看」里的 'I看看' 撞 InfoQ）一律不执行。
    if fr.get("kind") == 2:
        try:
            from dlog import log
            log(f"   [OPENCODE] B 路兜底: 只命中前缀行「{fr.get('span')}」"
                f"→ 不执行（防假命中）", "MIC", sub=True)
        except Exception:
            pass
        return False
    tag = f"{fr['intent']}({fr['arg']})"
    if not (fr.get("additive") and not fr.get("blocked")):
        # 破坏性/非 additive：不在 B 路抢跑（交回原流程，由规则/模型判）
        try:
            from dlog import log
            log(f"   [OPENCODE] B 路命中 {tag}，但非 additive/破坏性 → 不抢跑", "MIC",
                sub=True)
        except Exception:
            pass
        return False
    if _akey_safe(fr["intent"], fr["arg"]) in getattr(agent, "_a_executed", set()):
        return False
    try:
        from dlog import log
        log(f"   [OPENCODE] B 路兜底命中 {tag} ← 「{(text or '').strip()}」", "MIC", sub=True)
    except Exception:
        pass
    ok = _record(agent, text, fr, "b_fallback", early=False)
    if not ok:
        try:
            from dlog import log
            log(f"   ⚠️ B 路兜底执行失败：{tag}（已消费本句，不再听写）", "WARN")
        except Exception:
            pass
        return True
    return True
